    fn detached_runtime_over(
        runtime_store: Arc<dyn meerkat_runtime::RuntimeStore>,
    ) -> DetachedCallbackJobRuntime {
        let binary: Arc<dyn BinaryBlobStore> = Arc::new(ObjectStoreBlobStore::memory());
        let blobs: Arc<dyn meerkat_core::BlobStore> = Arc::new(Base64BlobStoreAdapter::new(binary));
        let jobs: Arc<dyn meerkat::DetachedJobStore> =
            Arc::new(meerkat::MemoryDetachedJobStore::new());
        let delivery = GatewayRuntimeDelivery::new(runtime_store, Arc::clone(&jobs));
        DetachedCallbackJobRuntime::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            jobs,
            blobs,
        )
        .with_runtime_delivery(&delivery)
    }

    /// The shell job projector and the detached-job delivery runtime share
    /// one inbox: a delivery projected through the shell path wakes the
    /// delivery runtime's commit signal and is in its backlog. Two inboxes
    /// constructed separately over the same store agree on the backlog but
    /// never see each other's commits, which is what this pins.
    #[tokio::test]
    async fn a_shell_projected_delivery_wakes_the_delivery_runtime() {
        let runtime_store: Arc<dyn meerkat_runtime::RuntimeStore> =
            Arc::new(meerkat_runtime::InMemoryRuntimeStore::new());
        let job_store = Arc::new(meerkat::MemoryDetachedJobStore::new());
        let delivery = GatewayRuntimeDelivery::new(runtime_store, job_store.clone());
        let projector = delivery.shell_job_projector(
            job_store.clone(),
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
        );
        let binary: Arc<dyn BinaryBlobStore> = Arc::new(ObjectStoreBlobStore::memory());
        let blobs: Arc<dyn meerkat_core::BlobStore> = Arc::new(Base64BlobStoreAdapter::new(binary));
        let runtime = DetachedCallbackJobRuntime::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            job_store.clone(),
            blobs,
        )
        .with_runtime_delivery(&delivery);
        let commits = runtime
            .runtime_inbox
            .as_ref()
            .expect("the delivery runtime holds the gateway inbox")
            .subscribe_commits();

        let jobs = meerkat::DetachedJobService::new(job_store);
        let receipt = jobs
            .submit(meerkat::JobSpec::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                meerkat_core::SessionId::new(),
                meerkat::ExecutionIntentId::new(),
                meerkat::InteractionLineageId::new(),
                meerkat::ToolIdentity::new("shell", "1").expect("tool"),
                meerkat::RunnerIdentity::new("durable-shell", "1").expect("runner"),
                meerkat::RestartClass::Adoptable,
                meerkat::CanonicalArgumentsHash::new("hash-shared-inbox").expect("hash"),
                meerkat::JobSubmissionKey::new("shared-inbox").expect("submission key"),
            ))
            .await
            .expect("submit");
        let claim = jobs
            .claim_attempt(
                &receipt.job_id,
                meerkat::AttemptClaim::new(
                    meerkat::WorkerId::new("worker").expect("worker"),
                    1,
                    100,
                    meerkat::RunnerHandleRef::new("runner-handle").expect("handle"),
                ),
            )
            .await
            .expect("claim");
        jobs.complete_attempt(
            &receipt.job_id,
            (&claim).into(),
            2,
            Some(meerkat::JobResultRef::new("result").expect("result")),
        )
        .await
        .expect("complete");

        let pass = projector.project_pending(16).await.expect("project");
        assert!(
            !pass.projected.is_empty(),
            "the terminal is projected: {pass:?}"
        );
        assert!(
            commits.has_changed().expect("the inbox is alive"),
            "the shell path's commit must wake the delivery runtime's subscribers"
        );
        assert_eq!(
            runtime.runtime_inbox_backlog_count().await,
            Ok(u64::try_from(pass.projected.len()).expect("small"))
        );
    }

    /// A gateway-shaped callback job runtime with one completed job whose
    /// Event subscription targets `subscriber`. The delivery service is a
    /// concrete `PersistentSessionService` that acquires the explicit serving
    /// machine before its first runtime use.
    async fn event_delivery_fixture(
        temp: &std::path::Path,
        register_subscriber: bool,
    ) -> Result<
        (
            DetachedCallbackJobRuntime,
            Arc<meerkat_runtime::MeerkatMachine>,
            meerkat_core::SessionId,
            crate::MobRuntime,
        ),
        Box<dyn std::error::Error + Send + Sync>,
    > {
        let session_store: Arc<dyn meerkat::SessionStore> = Arc::new(
            meerkat_store::SqliteSessionStore::open(temp.join("sessions.sqlite3"))?,
        );
        let runtime_store: Arc<dyn meerkat_runtime::RuntimeStore> = Arc::new(
            meerkat_runtime::store::SqliteRuntimeStore::new(temp.join("runtime.sqlite3"))?,
        );
        let binary: Arc<dyn BinaryBlobStore> = Arc::new(ObjectStoreBlobStore::memory());
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(Base64BlobStoreAdapter::new(binary));
        let serving = Arc::new(
            meerkat_runtime::MeerkatMachine::persistent(
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            )
            .expect("acquire the RPC gateway fixture runtime machine"),
        );
        let job_store: Arc<dyn meerkat::DetachedJobStore> =
            Arc::new(meerkat::MemoryDetachedJobStore::new());
        let factory = meerkat::AgentFactory::new(temp);
        let mut builder = meerkat::FactoryAgentBuilder::new(factory, meerkat::Config::default());
        builder.default_detached_job_store = Some(Arc::clone(&job_store));
        let concrete: Arc<dyn meerkat_mob::MobSessionService> =
            Arc::new(meerkat_session::PersistentSessionService::new(
                builder,
                16,
                session_store,
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            ));
        let acquired = concrete
            .acquire_runtime_adapter(Some(Arc::clone(&serving)))
            .expect("acquire the event delivery fixture's serving runtime owner")
            .expect("the event delivery service exposes its runtime owner");
        assert!(
            acquired.shares_runtime_execution_owner_with(&serving),
            "event delivery and the session service must share their runtime owner"
        );

        let origin = meerkat_core::SessionId::new();
        let subscriber = meerkat_core::SessionId::new();
        if register_subscriber {
            serving.register_session(subscriber.clone()).await?;
        }

        let jobs = meerkat::DetachedJobService::new(Arc::clone(&job_store));
        let receipt = jobs
            .submit(meerkat::JobSpec::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                origin,
                meerkat::ExecutionIntentId::new(),
                meerkat::InteractionLineageId::new(),
                meerkat::ToolIdentity::new("weather", "1")?,
                meerkat::RunnerIdentity::new("weather.scan", "1")?,
                meerkat::RestartClass::NonResumable,
                meerkat::CanonicalArgumentsHash::new("hash-event-probe")?,
                meerkat::JobSubmissionKey::new("event-probe")?,
            ))
            .await?;
        jobs.subscribe(
            &receipt.job_id,
            meerkat::JobSubscription::new(
                meerkat::JobSubscriptionId::new("event-probe")?,
                subscriber.clone(),
                meerkat::JobDeliveryKind::Event {
                    handling_mode: meerkat_core::HandlingMode::Queue,
                },
            ),
        )
        .await?;
        let claim = jobs
            .claim_attempt(
                &receipt.job_id,
                meerkat::AttemptClaim::new(
                    meerkat::WorkerId::new("worker")?,
                    1,
                    100,
                    meerkat::RunnerHandleRef::new("runner-handle")?,
                ),
            )
            .await?;
        jobs.complete_attempt(
            &receipt.job_id,
            (&claim).into(),
            2,
            Some(meerkat::JobResultRef::new("result")?),
        )
        .await?;

        let delivery = GatewayRuntimeDelivery::new(runtime_store, Arc::clone(&job_store));
        let runtime = DetachedCallbackJobRuntime::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            job_store,
            blob_store,
        )
        .with_runtime_delivery(&delivery);
        let definition = meerkat_mob::MobDefinition::from_toml(&format!(
            "[mob]\nid = \"delivery-{}\"\n\n[profiles.worker]\nmodel = \"gpt-5.5\"\n",
            uuid::Uuid::new_v4()
        ))?;
        let owner = crate::MobRuntime::bootstrap(
            MobBootstrapSpec::new(definition, MobStorage::in_memory(), concrete)
                .with_session_runtime_adapter(Arc::clone(&serving))?
                .with_runtime_delivery(delivery.composition.clone()),
        )
        .await?;
        tokio::time::timeout(Duration::from_secs(10), async {
            while delivery.composition.last_pass().is_none() {
                tokio::task::yield_now().await;
            }
        })
        .await?;
        Ok((runtime, serving, subscriber, owner))
    }

    /// A job Event delivery is admitted on the machine that serves the
    /// subscriber's session. The service acquires that explicit owner before
    /// registration, and the drain receives the same machine for admission.
    #[tokio::test]
    async fn a_job_event_delivery_is_admitted_on_the_serving_machine()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, serving, subscriber, _owner) =
            event_delivery_fixture(temp.path(), true).await?;

        let admitted = meerkat_runtime::SessionServiceRuntimeExt::list_active_inputs(
            serving.as_ref(),
            &subscriber,
        )
        .await?;
        assert_eq!(
            admitted.len(),
            1,
            "the job's Event delivery must be admitted on the serving machine"
        );
        let pass = runtime
            .runtime_delivery
            .as_ref()
            .expect("delivery")
            .last_pass()
            .expect("native pass");
        assert!(pass.blocked_sessions.is_empty(), "{pass:?}");
        Ok(())
    }

    /// Native owner health reports the blocked address and exact failures;
    /// unavailable row-level diagnostics must never masquerade as an empty list.
    #[tokio::test]
    async fn a_blocked_job_delivery_degrades_native_owner_health()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, _serving, _subscriber, _owner) =
            event_delivery_fixture(temp.path(), false).await?;
        let pass = runtime
            .runtime_delivery
            .as_ref()
            .expect("delivery")
            .last_pass()
            .expect("native pass");
        assert!(!pass.blocked_runtimes.is_empty(), "{pass:?}");
        assert!(!pass.failures.is_empty(), "{pass:?}");
        let projection = runtime.health_projection().await?;
        assert_eq!(projection["detached_jobs"]["status"], json!("degraded"));
        assert!(projection["detached_jobs"]["blocked_deliveries"].is_null());
        assert_eq!(
            projection["detached_jobs"]["blocked_deliveries_reading"],
            "unavailable"
        );
        assert_eq!(
            projection["detached_jobs"]["runtime_delivery_pass"]["failures"],
            json!(pass.failures)
        );
        Ok(())
    }

    /// A gateway-shaped callback job runtime for a `launch` authority, over a
    /// delivery composition whose mob boots under `mob` (the same authority in
    /// production; they differ only to model another launch arming the shared
    /// owner). Every store is persistent, as the gateway composes them (SQLite
    /// sessions, runtime and detached jobs, a local blob store): an executor's
    /// monitor manager refuses non-persistent job and blob stores. The
    /// controls still never close and reopen them, so they prove the recovery
    /// guard and the census, not durable reopening. With `stale_monitor_job`
    /// it holds one persisted shell monitor job whose worker lease lapsed long
    /// ago: the row startup monitor recovery would expire, lose and
    /// terminalize.
    async fn launch_job_fixture(
        temp: &std::path::Path,
        launch: crate::mob_composition_manifest::CompositionAuthority,
        mob: crate::mob_composition_manifest::CompositionAuthority,
        stale_monitor_job: bool,
    ) -> Result<
        (
            DetachedCallbackJobRuntime,
            Option<meerkat::JobId>,
            crate::MobRuntime,
        ),
        Box<dyn std::error::Error + Send + Sync>,
    > {
        let session_store: Arc<dyn meerkat::SessionStore> = Arc::new(
            meerkat_store::SqliteSessionStore::open(temp.join("sessions.sqlite3"))?,
        );
        let runtime_store: Arc<dyn meerkat_runtime::RuntimeStore> = Arc::new(
            meerkat_runtime::store::SqliteRuntimeStore::new(temp.join("runtime.sqlite3"))?,
        );
        let binary: Arc<dyn BinaryBlobStore> =
            Arc::new(ObjectStoreBlobStore::local(temp.join("blobs"))?);
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(Base64BlobStoreAdapter::new(binary));
        let serving = Arc::new(
            meerkat_runtime::MeerkatMachine::persistent(
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            )
            .expect("acquire the launch fixture runtime machine"),
        );
        let job_store: Arc<dyn meerkat::DetachedJobStore> = Arc::new(
            meerkat::SqliteDetachedJobStore::open(temp.join("jobs.sqlite3"))?,
        );
        let factory = meerkat::AgentFactory::new(temp);
        let mut builder = meerkat::FactoryAgentBuilder::new(factory, meerkat::Config::default());
        builder.default_detached_job_store = Some(Arc::clone(&job_store));
        let concrete: Arc<dyn meerkat_mob::MobSessionService> =
            Arc::new(meerkat_session::PersistentSessionService::new(
                builder,
                16,
                session_store,
                Arc::clone(&runtime_store),
                Arc::clone(&blob_store),
            ));
        let acquired = concrete
            .acquire_runtime_adapter(Some(Arc::clone(&serving)))
            .expect("acquire the launch fixture's serving runtime owner")
            .expect("the launch fixture service exposes its runtime owner");
        assert!(acquired.shares_runtime_execution_owner_with(&serving));

        let stale_job = if stale_monitor_job {
            // No runner specification: the job is listed, and recovered, but
            // cannot be hydrated after its recovery.
            let jobs = meerkat::DetachedJobService::new(Arc::clone(&job_store));
            let receipt = jobs
                .submit(meerkat::JobSpec::new(
                    crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                    meerkat_core::SessionId::new(),
                    meerkat::ExecutionIntentId::new(),
                    meerkat::InteractionLineageId::new(),
                    meerkat::ToolIdentity::new("shell", "1")?,
                    meerkat::RunnerIdentity::new("meerkat.shell", "1")?,
                    meerkat::RestartClass::NonResumable,
                    meerkat::CanonicalArgumentsHash::new("hash-stale-monitor")?,
                    meerkat::JobSubmissionKey::new("stale-monitor")?,
                ))
                .await?;
            // Claimed long ago: its worker lease lapsed 100 ms after the epoch.
            jobs.claim_attempt(
                &receipt.job_id,
                meerkat::AttemptClaim::new(
                    meerkat::WorkerId::new("worker")?,
                    1,
                    100,
                    meerkat::RunnerHandleRef::new("runner-handle")?,
                ),
            )
            .await?;
            Some(receipt.job_id)
        } else {
            None
        };

        let delivery = GatewayRuntimeDelivery::new(runtime_store, Arc::clone(&job_store));
        let runtime = DetachedCallbackJobRuntime::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            job_store,
            blob_store,
        )
        .with_runtime_delivery(&delivery)
        .with_launch_authority(launch)
        .with_monitor_shell(temp.to_path_buf(), true);
        let definition = meerkat_mob::MobDefinition::from_toml(&format!(
            "[mob]\nid = \"launch-{}\"\n\n[profiles.worker]\nmodel = \"gpt-5.5\"\n",
            uuid::Uuid::new_v4()
        ))?;
        let owner = crate::MobRuntime::bootstrap(
            MobBootstrapSpec::new(definition, MobStorage::in_memory(), concrete)
                .with_session_runtime_adapter(Arc::clone(&serving))?
                .with_runtime_delivery(delivery.composition.clone())
                .with_composition_authority(mob),
        )
        .await?;
        Ok((runtime, stale_job, owner))
    }

    /// A candidate launch's delivery owner is unarmed by the composition's
    /// own decision, and health says exactly that: owner state
    /// `quiesced_candidate`, not running, no invented pass, the backlog census
    /// still counted, and no owner penalty on the reading.
    #[tokio::test]
    async fn a_candidate_launch_reports_a_quiesced_delivery_owner_without_an_owner_penalty()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, _, _owner) = launch_job_fixture(
            temp.path(),
            crate::mob_composition_manifest::CompositionAuthority::NonAuthoritative,
            crate::mob_composition_manifest::CompositionAuthority::NonAuthoritative,
            false,
        )
        .await?;
        let projection = runtime.health_projection().await?;
        assert_eq!(projection["status"], json!("ok"), "{projection}");
        let jobs = &projection["detached_jobs"];
        assert_eq!(
            jobs["runtime_delivery_owner"],
            json!("quiesced_candidate"),
            "{projection}"
        );
        assert_eq!(jobs["runtime_delivery_owner_running"], json!(false));
        assert_eq!(jobs["runtime_delivery_pass"], Value::Null);
        assert_eq!(jobs["runtime_inbox_backlog"], json!(0));
        assert_eq!(jobs["runtime_inbox_backlog_reading"], json!("counted"));
        Ok(())
    }

    /// Executor control for the health marker: an armed owner reads
    /// `running`, and once it stops it keeps its failure semantics - not
    /// running and unreadable - and never passes for a quiesced candidate.
    #[tokio::test]
    async fn an_executor_whose_delivery_owner_stopped_still_reads_unreadable()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, _, owner) = launch_job_fixture(
            temp.path(),
            crate::mob_composition_manifest::CompositionAuthority::Authoritative,
            crate::mob_composition_manifest::CompositionAuthority::Authoritative,
            false,
        )
        .await?;
        let delivery = runtime
            .runtime_delivery
            .clone()
            .expect("the launch fixture composes delivery");
        tokio::time::timeout(Duration::from_secs(10), async {
            while delivery.last_pass().is_none() {
                tokio::task::yield_now().await;
            }
        })
        .await?;
        let running = runtime.health_projection().await?;
        assert_eq!(
            running["detached_jobs"]["runtime_delivery_owner"],
            json!("running"),
            "{running}"
        );
        owner.stop_runtime_delivery();
        assert!(!delivery.is_running());
        let stopped = runtime.health_projection().await?;
        assert_eq!(stopped["status"], json!("unreadable"), "{stopped}");
        assert_eq!(
            stopped["detached_jobs"]["runtime_delivery_owner"],
            json!("not_running"),
            "{stopped}"
        );
        assert_eq!(
            stopped["detached_jobs"]["runtime_delivery_owner_running"],
            json!(false)
        );
        Ok(())
    }

    /// Candidate startup recovers no durable monitor and creates no
    /// monitor manager. The persisted monitor job with a lapsed worker lease
    /// stays exactly as stored - no expiry, loss, retry, cancellation or
    /// start, and nothing reaches the runtime inbox - while the health census
    /// still reports its stale lease.
    #[tokio::test]
    async fn candidate_startup_recovers_no_persisted_monitor_job()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, job_id, _owner) = launch_job_fixture(
            temp.path(),
            crate::mob_composition_manifest::CompositionAuthority::NonAuthoritative,
            crate::mob_composition_manifest::CompositionAuthority::NonAuthoritative,
            true,
        )
        .await?;
        let job_id = job_id.expect("the fixture holds a stale monitor job");
        let before = runtime.service.get(&job_id).await?.expect("stored job");
        assert_eq!(before.phase, meerkat::JobPhase::Running);
        // The 1 Hz driver retries recovery every tick; so does this. The
        // store is checked before the outcomes: a candidate that recovered
        // fails on the untouched job, not on a later hydration error.
        let mut recoveries = Vec::new();
        for _ in 0..3 {
            recoveries.push(runtime.recover_monitor_jobs().await);
        }
        let after = runtime.service.get(&job_id).await?.expect("stored job");
        assert_eq!(
            after, before,
            "a candidate must leave the persisted monitor job untouched"
        );
        assert!(
            runtime.monitor_managers.lock().await.is_empty(),
            "a candidate creates no monitor manager"
        );
        for recovery in recoveries {
            recovery?;
        }
        assert!(!runtime.monitor_recovery_completed.load(Ordering::Acquire));
        assert_eq!(runtime.runtime_inbox_backlog_count().await, Ok(0));
        let projection = runtime.health_projection().await?;
        assert_eq!(
            projection["status"],
            json!("degraded"),
            "the stale lease stays a census finding: {projection}"
        );
        assert_eq!(
            projection["detached_jobs"]["runtime_delivery_owner"],
            json!("quiesced_candidate")
        );
        Ok(())
    }

    /// Race control: a candidate launch whose shared delivery composition
    /// another, authoritative launch armed keeps its own fixed decision. Its
    /// startup still recovers no monitor and creates no manager, and health
    /// reports the live owner as running, never as a quiesced candidate.
    #[tokio::test]
    async fn a_candidate_launch_over_a_live_shared_owner_still_recovers_no_monitor()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, job_id, _owner) = launch_job_fixture(
            temp.path(),
            crate::mob_composition_manifest::CompositionAuthority::NonAuthoritative,
            crate::mob_composition_manifest::CompositionAuthority::Authoritative,
            true,
        )
        .await?;
        let delivery = runtime
            .runtime_delivery
            .clone()
            .expect("the launch fixture composes delivery");
        tokio::time::timeout(Duration::from_secs(10), async {
            while delivery.last_pass().is_none() {
                tokio::task::yield_now().await;
            }
        })
        .await?;
        assert!(
            delivery.is_running(),
            "another launch armed the shared owner"
        );
        let job_id = job_id.expect("the fixture holds a stale monitor job");
        let before = runtime.service.get(&job_id).await?.expect("stored job");
        let recovery = runtime.recover_monitor_jobs().await;
        let after = runtime.service.get(&job_id).await?.expect("stored job");
        assert_eq!(
            after, before,
            "the candidate's own decision, not the shared owner, governs recovery"
        );
        assert!(runtime.monitor_managers.lock().await.is_empty());
        recovery?;
        let projection = runtime.health_projection().await?;
        assert_eq!(
            projection["detached_jobs"]["runtime_delivery_owner"],
            json!("running"),
            "{projection}"
        );
        Ok(())
    }

    /// Executor control for monitor recovery: the same persisted monitor job
    /// is recovered at startup, through a monitor manager, exactly as before.
    /// `JobManager::list_jobs` recovers first (lease expiry, loss, terminal)
    /// and then hydrates every listed job from its runner specification; the
    /// fixture's job has none, so the call then fails with exactly that
    /// refusal, after the recovery effects and never as a launch gate.
    #[tokio::test]
    async fn executor_startup_still_recovers_a_persisted_monitor_job()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let temp = tempfile::tempdir()?;
        let (runtime, job_id, _owner) = launch_job_fixture(
            temp.path(),
            crate::mob_composition_manifest::CompositionAuthority::Authoritative,
            crate::mob_composition_manifest::CompositionAuthority::Authoritative,
            true,
        )
        .await?;
        let job_id = job_id.expect("the fixture holds a stale monitor job");
        let before = runtime.service.get(&job_id).await?.expect("stored job");
        assert_eq!(before.phase, meerkat::JobPhase::Running);
        let recovery = runtime.recover_monitor_jobs().await;
        let after = runtime.service.get(&job_id).await?.expect("stored job");
        assert!(
            after.revision > before.revision && after.phase != meerkat::JobPhase::Running,
            "executor recovery must act on the lapsed lease: {before:?} -> {after:?}"
        );
        assert_eq!(runtime.monitor_managers.lock().await.len(), 1);
        let Err(error) = recovery else {
            panic!("the spec-less fixture job cannot be hydrated after its recovery");
        };
        assert!(
            error.contains(&format!("job {job_id} has no runner specification")),
            "{error}"
        );
        assert!(!runtime.monitor_recovery_completed.load(Ordering::Acquire));
        Ok(())
    }

    #[derive(Clone, Default)]
    struct CaptureWriter(Arc<std::sync::Mutex<Vec<u8>>>);

    impl CaptureWriter {
        fn contents(&self) -> String {
            String::from_utf8_lossy(
                &self
                    .0
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner),
            )
            .into_owned()
        }
    }

    impl std::io::Write for CaptureWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.0
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .extend_from_slice(buf);
            Ok(buf.len())
        }

        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for CaptureWriter {
        type Writer = CaptureWriter;

        fn make_writer(&'a self) -> Self::Writer {
            self.clone()
        }
    }

    /// Regression for the 1 Hz `durable callback health projection failed
    /// ... list_runtime_delivery_authorities` WARN. The gateway hands the
    /// detached job runtime its composed runtime store, and a store wrapper
    /// that did not forward the one cross-runtime delivery read made every
    /// delivery-driver tick fail on the trait default. Every tick must count,
    /// and nothing may be classified as unsupported.
    #[tokio::test]
    async fn health_projection_counts_the_runtime_inbox_through_the_composed_store() {
        let runtime_store: Arc<dyn meerkat_runtime::RuntimeStore> =
            Arc::new(meerkat_runtime::InMemoryRuntimeStore::new());
        let runtime = detached_runtime_over(runtime_store);
        for tick in 0..3 {
            let projection = runtime
                .health_projection()
                .await
                .unwrap_or_else(|error| panic!("tick {tick}: health projection failed: {error}"));
            // This helper composes delivery but arms no native owner, so the
            // owner's pass dimension has nothing to read and the overall
            // status says so. The backlog census itself is read and counted.
            assert_eq!(projection["status"], json!("unreadable"));
            assert_eq!(
                projection["detached_jobs"]["runtime_delivery_pass"],
                Value::Null
            );
            assert_eq!(
                projection["detached_jobs"]["runtime_inbox_backlog"],
                json!(0)
            );
            assert_eq!(
                projection["detached_jobs"]["runtime_inbox_backlog_reading"],
                json!("counted")
            );
        }
        assert!(
            !runtime
                .runtime_inbox_unsupported_announced
                .load(Ordering::Acquire),
            "a store that answers must never be classified as unsupported"
        );
        assert_eq!(runtime.runtime_inbox_backlog_count().await, Ok(0));
    }

    /// A runtime store that genuinely cannot enumerate delivery authorities
    /// is a typed store property, not a per-tick fault: the projection
    /// succeeds with `runtime_inbox_backlog: null`, the dimension reads
    /// `unreadable` (never a fabricated zero), and the WARN naming the
    /// operation fires exactly once across many ticks.
    #[tokio::test]
    async fn health_projection_types_an_unsupported_runtime_inbox_read_and_warns_once() {
        let runtime = detached_runtime_over(Arc::new(DeliveryCensusFailingStore {
            inner: meerkat_runtime::InMemoryRuntimeStore::new(),
            failure: || {
                meerkat_runtime::store::RuntimeStoreError::Unsupported(
                    "list_runtime_delivery_authorities".to_string(),
                )
            },
        }));
        let writer = CaptureWriter::default();
        let subscriber = tracing_subscriber::fmt()
            .with_writer(writer.clone())
            .with_max_level(tracing::Level::WARN)
            .finish();
        // A second registered Dispatch keeps callsite interest from being
        // cached `never` by threads without a subscriber.
        let _anchor = tracing::Dispatch::new(tracing_subscriber::Registry::default());
        let _guard = tracing::subscriber::set_default(subscriber);

        for tick in 0..5 {
            let projection = runtime
                .health_projection()
                .await
                .unwrap_or_else(|error| panic!("tick {tick}: unsupported must not fail: {error}"));
            assert_eq!(projection["status"], json!("unreadable"));
            assert_eq!(projection["detached_jobs"]["status"], json!("unreadable"));
            assert_eq!(
                projection["detached_jobs"]["runtime_inbox_backlog"],
                Value::Null,
                "an unsupported census must not publish a number"
            );
            assert_eq!(
                projection["detached_jobs"]["runtime_inbox_backlog_reading"],
                json!("unsupported")
            );
        }
        let warnings = writer.contents();
        assert_eq!(
            warnings
                .matches("does not support the runtime inbox backlog read")
                .count(),
            1,
            "the unsupported store is announced exactly once, got: {warnings}"
        );
        assert!(
            warnings.contains("list_runtime_delivery_authorities"),
            "the announcement names the refused operation, got: {warnings}"
        );
        assert!(
            runtime
                .runtime_inbox_unsupported_announced
                .load(Ordering::Acquire)
        );
        // The u64 wire contract cannot carry "unreadable": a typed error, not 0.
        let wire = runtime.runtime_inbox_backlog_count().await;
        assert!(
            wire.as_ref()
                .is_err_and(|error| error.contains("list_runtime_delivery_authorities")),
            "jobs/health must refuse rather than fabricate a zero, got {wire:?}"
        );
    }

    /// A store that CAN answer but fails is a real fault and must keep
    /// surfacing on every tick with its own text; it must never be folded
    /// into the once-only unsupported classification.
    #[tokio::test]
    async fn health_projection_surfaces_a_real_runtime_inbox_read_failure_every_tick() {
        let runtime = detached_runtime_over(Arc::new(DeliveryCensusFailingStore {
            inner: meerkat_runtime::InMemoryRuntimeStore::new(),
            failure: || {
                meerkat_runtime::store::RuntimeStoreError::ReadFailed(
                    "runtime.sqlite: disk I/O error".to_string(),
                )
            },
        }));
        for tick in 0..3 {
            let error = runtime
                .health_projection()
                .await
                .expect_err("a real read failure must surface on every tick");
            assert!(
                error.contains("disk I/O error"),
                "tick {tick}: the store's own failure text must survive, got: {error}"
            );
        }
        assert!(
            !runtime
                .runtime_inbox_unsupported_announced
                .load(Ordering::Acquire),
            "a read failure is not an unsupported store"
        );
    }

    #[test]
    fn runtime_inbox_backlog_classification_is_typed() {
        assert_eq!(
            classify_runtime_inbox_backlog(Ok(3)),
            Ok(RuntimeInboxBacklog::Counted(3))
        );
        assert_eq!(
            classify_runtime_inbox_backlog(Err(meerkat_runtime::RuntimeDeliveryError::Store(
                meerkat_runtime::store::RuntimeStoreError::Unsupported("list_x".to_string()),
            ))),
            Ok(RuntimeInboxBacklog::Unsupported {
                operation: "list_x".to_string()
            })
        );
        let corrupt = classify_runtime_inbox_backlog(Err(
            meerkat_runtime::RuntimeDeliveryError::Corrupt("cursor ahead of sequence".to_string()),
        ));
        assert!(corrupt.is_err_and(|error| error.contains("cursor ahead of sequence")));
        let read_failed =
            classify_runtime_inbox_backlog(Err(meerkat_runtime::RuntimeDeliveryError::Store(
                meerkat_runtime::store::RuntimeStoreError::ReadFailed("locked".to_string()),
            )));
        assert!(read_failed.is_err_and(|error| error.contains("locked")));
        assert_eq!(
            RuntimeInboxBacklog::Counted(0).reading(),
            meerkat::JobHealthReading::Ok
        );
        assert_eq!(
            RuntimeInboxBacklog::Counted(1).reading(),
            meerkat::JobHealthReading::Degraded
        );
        assert_eq!(
            RuntimeInboxBacklog::Unsupported {
                operation: "list_x".to_string()
            }
            .reading(),
            meerkat::JobHealthReading::Unreadable
        );
    }

    #[test]
    fn callback_runner_ownership_requires_exact_tool_runner_and_version() {
        let binary: Arc<dyn BinaryBlobStore> = Arc::new(ObjectStoreBlobStore::memory());
        let blobs: Arc<dyn meerkat_core::BlobStore> = Arc::new(Base64BlobStoreAdapter::new(binary));
        let runtime = DetachedCallbackJobRuntime::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            Arc::new(meerkat::MemoryDetachedJobStore::new()),
            blobs,
        );
        let dispatcher = CallbackToolDispatcher::new(
            test_callback_bridge(),
            "build-1".to_string(),
            vec![
                CallbackToolSpec::parse(&json!({
                    "name": "security_scan",
                    "execution": {
                        "mode": "detached",
                        "runner": {"name": "example.security_scan", "version": "1"},
                        "restart_class": "adoptable",
                        "idempotency_scope": "interaction_and_arguments",
                        "submission_timeout_ms": 30000
                    }
                }))
                .expect("tool spec"),
            ],
            Some(runtime.clone()),
        );
        assert!(
            dispatcher.reconcile_registered_catalog,
            "the first exact callback owner must trigger recovery"
        );
        let duplicate = CallbackToolDispatcher::new(
            test_callback_bridge(),
            "build-2".to_string(),
            vec![
                CallbackToolSpec::parse(&json!({
                    "name": "security_scan",
                    "execution": {
                        "mode": "detached",
                        "runner": {"name": "example.security_scan", "version": "1"},
                        "restart_class": "adoptable",
                        "idempotency_scope": "interaction_and_arguments",
                        "submission_timeout_ms": 30000
                    }
                }))
                .expect("tool spec"),
            ],
            Some(runtime.clone()),
        );
        assert!(
            !duplicate.reconcile_registered_catalog,
            "rebuilding an already-known exact owner must not start a duplicate recovery census"
        );
        let later_runner = CallbackToolDispatcher::new(
            test_callback_bridge(),
            "build-3".to_string(),
            vec![
                CallbackToolSpec::parse(&json!({
                    "name": "report_export",
                    "execution": {
                        "mode": "detached",
                        "runner": {"name": "example.report_export", "version": "1"},
                        "restart_class": "adoptable",
                        "idempotency_scope": "interaction_and_arguments",
                        "submission_timeout_ms": 30000
                    }
                }))
                .expect("tool spec"),
            ],
            Some(runtime.clone()),
        );
        assert!(
            later_runner.reconcile_registered_catalog,
            "a later exact owner must get its own recovery census"
        );
        let make_spec = |tool: &str, runner: &str, version: &str| {
            meerkat::JobSpec::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                meerkat_core::SessionId::parse("019f74fb-1907-7b21-932d-ab22c4d1f503")
                    .expect("session"),
                meerkat::ExecutionIntentId::from_string(format!("intent:{tool}")).expect("intent"),
                meerkat::InteractionLineageId::from_string(format!("lineage:{tool}"))
                    .expect("lineage"),
                meerkat::ToolIdentity::new(tool, version).expect("tool"),
                meerkat::RunnerIdentity::new(runner, version).expect("runner"),
                meerkat::RestartClass::Adoptable,
                meerkat::CanonicalArgumentsHash::new(format!("sha256:{}", "a".repeat(64)))
                    .expect("hash"),
                meerkat::JobSubmissionKey::new(format!("submission:{tool}:{runner}:{version}"))
                    .expect("submission"),
            )
        };
        assert!(runtime.owns_callback_job(&make_spec(
            "security_scan",
            "example.security_scan",
            "1"
        )));
        assert!(!runtime.owns_callback_job(&make_spec("other_tool", "example.security_scan", "1")));
        assert!(!runtime.owns_callback_job(&make_spec(
            "security_scan",
            "example.security_scan",
            "2"
        )));
    }

    #[tokio::test]
    async fn callback_reconcile_rehydrates_exact_committed_authority_without_advancing_fence() {
        let store = Arc::new(meerkat::MemoryDetachedJobStore::new());
        let service = meerkat::DetachedJobService::new(store.clone());
        let session_id = meerkat_core::SessionId::parse("019f74fb-1907-7b21-932d-ab22c4d1f532")
            .expect("session id");
        let spec = meerkat::JobSpec::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            session_id,
            meerkat::ExecutionIntentId::from_string("intent:reconcile").expect("intent"),
            meerkat::InteractionLineageId::from_string("lineage:reconcile").expect("lineage"),
            meerkat::ToolIdentity::new("security_scan", "1").expect("tool"),
            meerkat::RunnerIdentity::new("example.security_scan", "1").expect("runner"),
            meerkat::RestartClass::Adoptable,
            meerkat::CanonicalArgumentsHash::new(format!("sha256:{}", "a".repeat(64)))
                .expect("arguments hash"),
            meerkat::JobSubmissionKey::new("callback:reconcile").expect("submission key"),
        );
        let receipt = service.submit(spec).await.expect("submit");
        let claim = service
            .claim_attempt(
                &receipt.job_id,
                meerkat::AttemptClaim::new(
                    meerkat::WorkerId::new("worker-1").expect("worker"),
                    100,
                    u64::MAX,
                    meerkat::RunnerHandleRef::new("external:scan-1").expect("handle"),
                ),
            )
            .await
            .expect("claim");

        let (stdout_tx, mut stdout_rx) = mpsc::channel::<GatewayStdoutLine>(4);
        let bridge = StdioCallbackBridge::new(stdout_tx);
        let binary: Arc<dyn BinaryBlobStore> = Arc::new(ObjectStoreBlobStore::memory());
        let blobs: Arc<dyn meerkat_core::BlobStore> = Arc::new(Base64BlobStoreAdapter::new(binary));
        let dispatcher = CallbackToolDispatcher::new(
            bridge.clone(),
            "build-1".to_string(),
            vec![
                CallbackToolSpec::parse(&json!({
                    "name": "security_scan",
                    "execution": {
                        "mode": "detached",
                        "runner": {"name": "example.security_scan", "version": "1"},
                        "restart_class": "adoptable",
                        "idempotency_scope": "interaction_and_arguments",
                        "submission_timeout_ms": 30000
                    }
                }))
                .expect("tool spec"),
            ],
            Some(DetachedCallbackJobRuntime::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                store.clone(),
                blobs,
            )),
        );
        let reconcile = tokio::spawn(async move { dispatcher.reconcile_detached_jobs().await });
        let request_line = stdout_rx.recv().await.expect("reconcile callback");
        let request: Value = serde_json::from_str(&request_line).expect("callback json");
        assert_eq!(
            request.pointer("/params/attempts/0/authority/fence"),
            Some(&json!(claim.fence.get()))
        );
        assert_eq!(
            request.pointer("/params/attempts/0/authority/attempt_id"),
            Some(&json!(claim.attempt_id.to_string()))
        );
        assert_eq!(
            request.pointer("/params/attempts/0/runner_handle"),
            Some(&json!("external:scan-1"))
        );
        bridge
            .route_callback_response(json!({
                "jsonrpc": "2.0",
                "id": request["id"].clone(),
                "result": {
                    "live_attempts": [{
                        "job_id": receipt.job_id.to_string(),
                        "attempt_id": claim.attempt_id.to_string(),
                        "fence": claim.fence.get()
                    }]
                }
            }))
            .await;
        reconcile
            .await
            .expect("reconcile task")
            .expect("reconcile succeeds");

        let reopened = meerkat::DetachedJobStore::get(&*store, &receipt.job_id)
            .await
            .expect("read")
            .expect("job");
        assert_eq!(reopened.machine_state.attempt_count, 1);
        assert_eq!(reopened.machine_state.current_fence, claim.fence.get());
        assert_eq!(
            reopened.machine_state.current_attempt_id.as_deref(),
            Some(claim.attempt_id.as_str())
        );
    }

    fn callback_arguments_payload(data: String) -> meerkat_core::BlobPayload {
        meerkat_core::BlobPayload {
            blob_id: meerkat_core::BlobId::new("callback-arguments"),
            media_type: CALLBACK_ARGUMENTS_MEDIA_TYPE.to_string(),
            data,
        }
    }

    fn standard_base64(text: &str) -> String {
        base64::Engine::encode(&base64::engine::general_purpose::STANDARD, text)
    }

    #[test]
    fn callback_arguments_decode_from_base64_and_from_legacy_literals_of_every_json_shape() {
        for text in [
            r#"{"target": "lan"}"#,
            r#"[1, "two", {"three": 3}]"#,
            r#""text""#,
            "-1.5",
            "0",
            "1234",
            "true",
            "false",
            "null",
            " \t\r\n{\"padded\": true}",
        ] {
            let expected: Value = serde_json::from_str(text).expect("valid JSON");
            assert_eq!(
                decode_callback_arguments(&callback_arguments_payload(text.to_string())),
                Ok(expected.clone()),
                "legacy literal {text:?}"
            );
            assert_eq!(
                decode_callback_arguments(&callback_arguments_payload(standard_base64(text))),
                Ok(expected),
                "base64 of {text:?}"
            );
        }
    }

    #[test]
    fn callback_arguments_require_exactly_the_callback_media_type() {
        for media_type in [
            "application/json",
            "application/vnd.meerkat.callback-arguments+json; charset=utf-8",
            "Application/vnd.meerkat.callback-arguments+json",
        ] {
            let mut payload = callback_arguments_payload("null".to_string());
            payload.media_type = media_type.to_string();
            assert!(
                decode_callback_arguments(&payload).is_err(),
                "{media_type} must not decode"
            );
        }
    }

    #[test]
    fn a_malformed_callback_argument_record_fails_in_the_form_its_first_token_selects() {
        // A JSON start token selects the literal form. "nope" is also valid
        // base64, and is still read only as a literal.
        for literal in ["nope", "{\"open\": ", " [1,"] {
            let expected = serde_json::from_str::<Value>(literal)
                .expect_err("malformed literal")
                .to_string();
            assert_eq!(
                decode_callback_arguments(&callback_arguments_payload(literal.to_string())),
                Err(expected),
                "{literal:?}"
            );
        }
        // Anything else is the strict base64 of the original text: no
        // whitespace trimming, no missing padding, no byte order mark.
        for encoded in [
            format!(" {}", standard_base64("{}")),
            format!("{}\n", standard_base64("{}")),
            standard_base64("{}").trim_end_matches('=').to_string(),
            format!("\u{feff}{}", standard_base64("{}")),
        ] {
            let error = decode_callback_arguments(&callback_arguments_payload(encoded.clone()))
                .expect_err("malformed base64");
            assert!(
                error.starts_with("invalid base64: "),
                "{encoded:?}: {error}"
            );
        }
        // Valid base64 of text that is not JSON is not read as a literal.
        let expected = serde_json::from_slice::<Value>(b"not json")
            .expect_err("not JSON")
            .to_string();
        assert_eq!(
            decode_callback_arguments(&callback_arguments_payload(standard_base64("not json"))),
            Err(expected)
        );
    }

    /// Open the persistent detached-job and blob stores a gateway opens over
    /// `root`, the blob store behind the real base64 adapter.
    fn open_detached_callback_test_stores(
        root: &std::path::Path,
    ) -> (
        Arc<dyn meerkat::DetachedJobStore>,
        Arc<dyn BinaryBlobStore>,
        Arc<dyn meerkat_core::BlobStore>,
    ) {
        let store: Arc<dyn meerkat::DetachedJobStore> = Arc::new(
            meerkat::SqliteDetachedJobStore::open(root.join("jobs.sqlite")).expect("job store"),
        );
        let binary: Arc<dyn BinaryBlobStore> =
            Arc::new(ObjectStoreBlobStore::local(root.join("blobs")).expect("blob store"));
        let blobs: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(Base64BlobStoreAdapter::new(binary.clone()));
        (store, binary, blobs)
    }

    fn detached_callback_test_dispatcher(
        store: Arc<dyn meerkat::DetachedJobStore>,
        blobs: Arc<dyn meerkat_core::BlobStore>,
    ) -> (
        Arc<CallbackToolDispatcher>,
        StdioCallbackBridge,
        mpsc::Receiver<GatewayStdoutLine>,
    ) {
        let (stdout_tx, stdout_rx) = mpsc::channel::<GatewayStdoutLine>(4);
        let bridge = StdioCallbackBridge::new(stdout_tx);
        let dispatcher = CallbackToolDispatcher::new(
            bridge.clone(),
            "build-1".to_string(),
            vec![
                CallbackToolSpec::parse(&json!({
                    "name": "security_scan",
                    "execution": {
                        "mode": "detached",
                        "runner": {"name": "example.security_scan", "version": "1"},
                        "restart_class": "adoptable",
                        "idempotency_scope": "tool_call",
                        "submission_timeout_ms": 30000
                    }
                }))
                .expect("tool spec"),
            ],
            Some(DetachedCallbackJobRuntime::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                store,
                blobs,
            )),
        );
        (Arc::new(dispatcher), bridge, stdout_rx)
    }

    fn detached_callback_test_context() -> meerkat_core::ToolDispatchContext {
        meerkat_core::ToolDispatchContext::default().with_runtime_identity(
            meerkat_core::SessionId::parse("019f74fb-1907-7b21-932d-ab22c4d1f532")
                .expect("session id"),
            Some(meerkat_core::interaction::InteractionId(
                uuid::Uuid::from_u128(0x5ca1_ab1e),
            )),
        )
    }

    fn resolve_detached_callback_test_plan(
        dispatcher: &Arc<CallbackToolDispatcher>,
        call: ToolCallView<'_>,
        context: &meerkat_core::ToolDispatchContext,
    ) -> meerkat_core::ResolvedToolExecutionPlan {
        meerkat_core::resolve_tool_execution_plan_fenced(
            dispatcher,
            call,
            context,
            &meerkat_core::ToolExecutionResolutionContext::new(
                meerkat_core::ToolDeadlineChain::new(vec![ToolDeadlineContributor::finite(
                    ToolDeadlineOwner::CoreToolDispatch,
                    Duration::from_secs(30),
                )])
                .expect("deadline chain"),
            ),
        )
        .expect("execution plan")
    }

    async fn submit_detached_callback_test_call(
        dispatcher: &Arc<CallbackToolDispatcher>,
        call: ToolCallView<'_>,
    ) -> Result<meerkat_contracts::JobReceipt, ToolError> {
        let context = detached_callback_test_context();
        let plan = resolve_detached_callback_test_plan(dispatcher, call, &context);
        let outcome =
            meerkat_core::dispatch_tool_execution_plan_fenced(dispatcher, call, &context, &plan)
                .await?;
        Ok(serde_json::from_str(&outcome.result.text_content()).expect("job receipt"))
    }

    /// Accept the next `callback/job/start` the gateway offers and return its
    /// parameters.
    async fn accept_detached_callback_start(
        bridge: &StdioCallbackBridge,
        stdout_rx: &mut mpsc::Receiver<GatewayStdoutLine>,
    ) -> Value {
        let line = tokio::time::timeout(Duration::from_secs(5), stdout_rx.recv())
            .await
            .expect("attempt start is offered")
            .expect("callback line");
        let request: Value = serde_json::from_str(&line).expect("callback json");
        assert_eq!(request["method"], "callback/job/start");
        bridge
            .route_callback_response(json!({
                "jsonrpc": "2.0",
                "id": request["id"].clone(),
                "result": {
                    "accepted": true,
                    "runner_handle": request["params"]["runner_handle"].clone()
                }
            }))
            .await;
        request["params"].clone()
    }

    /// A detached `security_scan` callback tool on `runner_version` of the runner
    /// every detached test call here uses.
    fn detached_security_scan(runner_version: &str) -> Value {
        json!({
            "name": "security_scan",
            "description": "Scan a target for known issues.",
            "input_schema": {"type": "object", "properties": {"target": {"type": "string"}}},
            "execution": {
                "mode": "detached",
                "runner": {"name": "example.security_scan", "version": runner_version},
                "restart_class": "adoptable",
                "idempotency_scope": "tool_call",
                "submission_timeout_ms": 30000
            }
        })
    }

    fn detached_callback_test_dispatcher_declaring(
        store: Arc<dyn meerkat::DetachedJobStore>,
        blobs: Arc<dyn meerkat_core::BlobStore>,
        tool: Value,
    ) -> (
        Arc<CallbackToolDispatcher>,
        StdioCallbackBridge,
        mpsc::Receiver<GatewayStdoutLine>,
    ) {
        let (stdout_tx, stdout_rx) = mpsc::channel::<GatewayStdoutLine>(4);
        let bridge = StdioCallbackBridge::new(stdout_tx);
        let dispatcher = CallbackToolDispatcher::new(
            bridge.clone(),
            "build-1".to_string(),
            vec![CallbackToolSpec::parse(&tool).expect("tool spec")],
            Some(DetachedCallbackJobRuntime::new(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                store,
                blobs,
            )),
        );
        (Arc::new(dispatcher), bridge, stdout_rx)
    }

    /// A gateway on the stores under `root` submits a detached `security_scan`
    /// call under `tool`, and its host accepts the start. Returns the job id.
    async fn submit_and_start_detached_under(root: &std::path::Path, tool: Value) -> String {
        let args = serde_json::value::RawValue::from_string(r#"{"target":"build-7"}"#.to_string())
            .expect("raw arguments");
        let call = ToolCallView {
            id: "tc-runner-version",
            name: "security_scan",
            args: &args,
        };
        let (store, _binary, blobs) = open_detached_callback_test_stores(root);
        let (dispatcher, bridge, mut stdout_rx) =
            detached_callback_test_dispatcher_declaring(store, blobs, tool);
        let receipt = submit_detached_callback_test_call(&dispatcher, call)
            .await
            .expect("detached submit");
        accept_detached_callback_start(&bridge, &mut stdout_rx).await;
        receipt.job_id
    }

    /// A detached `security_scan` job on runner `runner_version`, admitted to the
    /// stores under `root` and never claimed: queued, as a gateway that exits
    /// between a submit and its first start leaves it. Returns the job id.
    async fn queue_detached_job_on_runner(root: &std::path::Path, runner_version: &str) -> String {
        use base64::Engine as _;
        let (store, _binary, blobs) = open_detached_callback_test_stores(root);
        let specification = blobs
            .put_artifact(
                CALLBACK_ARGUMENTS_MEDIA_TYPE,
                &base64::engine::general_purpose::STANDARD.encode(br#"{"target":"build-8"}"#),
            )
            .await
            .expect("callback arguments");
        let spec = meerkat::JobSpec::new(
            crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
            meerkat_core::SessionId::parse("019f74fb-1907-7b21-932d-ab22c4d1f532")
                .expect("session id"),
            meerkat::ExecutionIntentId::from_string("intent:queued").expect("intent"),
            meerkat::InteractionLineageId::from_string("lineage:queued").expect("lineage"),
            meerkat::ToolIdentity::new("security_scan", runner_version).expect("tool"),
            meerkat::RunnerIdentity::new("example.security_scan", runner_version).expect("runner"),
            meerkat::RestartClass::Adoptable,
            meerkat::CanonicalArgumentsHash::new(format!("sha256:{}", "b".repeat(64)))
                .expect("arguments hash"),
            meerkat::JobSubmissionKey::new("callback:queued").expect("submission key"),
        )
        .with_runner_specification_ref(
            meerkat::RunnerSpecificationRef::new(specification.blob_id.to_string())
                .expect("specification ref"),
        );
        meerkat::DetachedJobService::new(store)
            .submit(spec)
            .await
            .expect("submit")
            .job_id
            .to_string()
    }

    /// The first callback request a gateway restarted on the stores under `root`,
    /// declaring `tool`, sends while it reconciles and starts the detached jobs it
    /// owns, if one comes within `wait`.
    async fn first_callback_after_restart(
        root: &std::path::Path,
        tool: Value,
        wait: Duration,
    ) -> Option<Value> {
        let (store, _binary, blobs) = open_detached_callback_test_stores(root);
        let (dispatcher, _bridge, mut stdout_rx) =
            detached_callback_test_dispatcher_declaring(store, blobs, tool);
        let _reconcile = tokio::spawn(async move { dispatcher.reconcile_detached_jobs().await });
        let line = tokio::time::timeout(wait, stdout_rx.recv()).await.ok()??;
        Some(serde_json::from_str(&line).expect("callback json"))
    }

    /// A gateway takes over only the detached jobs of the runner versions it
    /// registers, which is what lets a host change a tool safely: give it a new
    /// runner version (the 0.9.3 Known limitation). Restarted on runner version 2,
    /// a gateway is not offered the running attempt of a job runner version 1
    /// started; restarted on version 1 again, it is.
    #[tokio::test]
    async fn a_gateway_on_another_runner_version_is_not_offered_a_running_job() {
        let root = tempfile::tempdir().expect("temp dir");
        let job_id =
            submit_and_start_detached_under(root.path(), detached_security_scan("1")).await;
        let offer = first_callback_after_restart(
            root.path(),
            detached_security_scan("2"),
            Duration::from_secs(2),
        )
        .await;
        assert!(
            offer.is_none(),
            "a gateway on runner version 2 was offered version 1's job {job_id}: {offer:?}"
        );
        let offer = first_callback_after_restart(
            root.path(),
            detached_security_scan("1"),
            Duration::from_secs(5),
        )
        .await
        .expect("a gateway back on runner version 1 is offered its running job");
        assert_eq!(offer["method"], "callback/job/reconcile");
        assert_eq!(
            offer["params"]["attempts"][0]["authority"]["job_id"],
            job_id
        );
    }

    /// The start path keeps the same rule: restarted on runner version 2, a gateway
    /// does not start a queued job of runner version 1; restarted on version 1
    /// again, it does.
    #[tokio::test]
    async fn a_gateway_on_another_runner_version_does_not_start_a_queued_job() {
        let root = tempfile::tempdir().expect("temp dir");
        let job_id = queue_detached_job_on_runner(root.path(), "1").await;
        let start = first_callback_after_restart(
            root.path(),
            detached_security_scan("2"),
            Duration::from_secs(2),
        )
        .await;
        assert!(
            start.is_none(),
            "a gateway on runner version 2 started version 1's queued job {job_id}: {start:?}"
        );
        let start = first_callback_after_restart(
            root.path(),
            detached_security_scan("1"),
            Duration::from_secs(5),
        )
        .await
        .expect("a gateway back on runner version 1 starts its queued job");
        assert_eq!(start["method"], "callback/job/start");
        assert_eq!(start["params"]["authority"]["job_id"], job_id);
        assert_eq!(start["params"]["arguments"], json!({"target": "build-8"}));
    }

    /// Every callback request a gateway restarted on the stores under `root`,
    /// declaring `tool` as a launch of `authority`, sends within `wait` while it
    /// reconciles and starts the detached jobs it owns, and what its reconcile
    /// returned if it ended within that window.
    async fn callbacks_after_restart_as(
        root: &std::path::Path,
        tool: Value,
        authority: crate::mob_composition_manifest::CompositionAuthority,
        wait: Duration,
    ) -> (Vec<Value>, Option<Result<(), String>>) {
        let (store, _binary, blobs) = open_detached_callback_test_stores(root);
        let (stdout_tx, mut stdout_rx) = mpsc::channel::<GatewayStdoutLine>(4);
        let dispatcher = CallbackToolDispatcher::new(
            StdioCallbackBridge::new(stdout_tx),
            "build-1".to_string(),
            vec![CallbackToolSpec::parse(&tool).expect("tool spec")],
            Some(
                DetachedCallbackJobRuntime::new(
                    crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                    store,
                    blobs,
                )
                .with_launch_authority(authority),
            ),
        );
        let reconcile = tokio::spawn(async move { dispatcher.reconcile_detached_jobs().await });
        let deadline = tokio::time::Instant::now() + wait;
        let mut sent = Vec::new();
        while let Ok(Some(line)) = tokio::time::timeout_at(deadline, stdout_rx.recv()).await {
            sent.push(serde_json::from_str(&line).expect("callback json"));
        }
        let reconciled = if reconcile.is_finished() {
            Some(reconcile.await.expect("the reconcile task"))
        } else {
            reconcile.abort();
            None
        };
        (sent, reconciled)
    }

    /// The detached job `job_id` as the stores under `root` hold it.
    async fn stored_detached_job(root: &std::path::Path, job_id: &str) -> meerkat::JobSnapshot {
        let (store, _binary, _blobs) = open_detached_callback_test_stores(root);
        meerkat::DetachedJobService::new(store)
            .get(&meerkat::JobId::new(job_id).expect("job id"))
            .await
            .expect("read the job")
            .expect("the job is stored")
    }

    /// A candidate launch starts none of the detached callback jobs it finds
    /// queued: they are the authoritative launch's, and a start would run the
    /// host's tool a second time. Restarted as a candidate on the job's own
    /// runner version, the gateway sends the host nothing and the job stays
    /// queued at its revision; the authoritative restart that follows starts
    /// it once, with its arguments.
    #[tokio::test]
    async fn a_candidate_launch_starts_no_queued_detached_job() {
        use crate::mob_composition_manifest::CompositionAuthority;

        let root = tempfile::tempdir().expect("temp dir");
        let job_id = queue_detached_job_on_runner(root.path(), "1").await;
        let before = stored_detached_job(root.path(), &job_id).await;
        assert_eq!(before.phase, meerkat::JobPhase::Queued);

        let (sent, reconciled) = callbacks_after_restart_as(
            root.path(),
            detached_security_scan("1"),
            CompositionAuthority::NonAuthoritative,
            Duration::from_secs(2),
        )
        .await;
        assert!(
            sent.is_empty(),
            "a candidate sent the host {sent:?} for the queued job {job_id}"
        );
        assert_eq!(
            reconciled,
            Some(Ok(())),
            "a candidate's reconcile ends at once"
        );
        assert_eq!(
            stored_detached_job(root.path(), &job_id).await,
            before,
            "the job stays queued at its revision"
        );

        let (sent, _) = callbacks_after_restart_as(
            root.path(),
            detached_security_scan("1"),
            CompositionAuthority::Authoritative,
            Duration::from_secs(5),
        )
        .await;
        assert_eq!(sent.len(), 1, "one start, nothing else: {sent:?}");
        assert_eq!(sent[0]["method"], "callback/job/start");
        assert_eq!(sent[0]["params"]["authority"]["job_id"], job_id);
        assert_eq!(sent[0]["params"]["arguments"], json!({"target": "build-8"}));
    }

    #[tokio::test]
    async fn detached_callback_array_arguments_cross_the_base64_adapter_and_replay_after_reopen() {
        let root = tempfile::tempdir().expect("temp dir");
        let args =
            serde_json::value::RawValue::from_string(r#"[1, "two", {"three": 3}]"#.to_string())
                .expect("raw arguments");
        let call = ToolCallView {
            id: "tc-array",
            name: "security_scan",
            args: &args,
        };

        let (receipt, reference) = {
            let (store, binary, blobs) = open_detached_callback_test_stores(root.path());
            let (dispatcher, bridge, mut stdout_rx) =
                detached_callback_test_dispatcher(store.clone(), blobs);
            let receipt = submit_detached_callback_test_call(&dispatcher, call)
                .await
                .expect("detached submit");
            assert!(!receipt.deduplicated);
            let start = accept_detached_callback_start(&bridge, &mut stdout_rx).await;
            assert_eq!(
                start.get("arguments"),
                Some(&json!([1, "two", {"three": 3}]))
            );
            let admitted = store
                .get(&meerkat::JobId::new(&receipt.job_id).expect("job id"))
                .await
                .expect("read job")
                .expect("admitted job");
            let reference = admitted
                .spec
                .runner_specification_ref
                .clone()
                .expect("runner specification");
            assert_eq!(
                start.get("runner_specification_ref"),
                Some(&json!(reference.as_str()))
            );
            assert_eq!(admitted.machine_state.attempt_count, 1);
            // The adapter decoded the base64 the gateway wrote, so the binary
            // face holds exactly the argument bytes the call carried.
            let stored = binary
                .get_bytes(&meerkat_core::BlobId::new(reference.as_str()))
                .await
                .expect("stored arguments");
            assert_eq!(stored.media_type, CALLBACK_ARGUMENTS_MEDIA_TYPE);
            assert_eq!(&stored.data[..], args.get().as_bytes());
            (receipt, reference)
        };

        let (store, _binary, blobs) = open_detached_callback_test_stores(root.path());
        let (dispatcher, _bridge, _stdout_rx) =
            detached_callback_test_dispatcher(store.clone(), blobs);
        let replay = submit_detached_callback_test_call(&dispatcher, call)
            .await
            .expect("replayed submit");
        assert_eq!(replay.job_id, receipt.job_id);
        assert!(replay.deduplicated);
        let jobs = store.list_all(usize::MAX).await.expect("list jobs");
        assert_eq!(jobs.len(), 1);
        assert_eq!(
            jobs[0].spec.runner_specification_ref.as_ref(),
            Some(&reference)
        );
        assert_eq!(jobs[0].machine_state.attempt_count, 1);
    }

    #[tokio::test]
    async fn historical_raw_null_callback_arguments_replay_to_their_admitted_job_after_reopen() {
        let root = tempfile::tempdir().expect("temp dir");
        let null = serde_json::value::RawValue::from_string("null".to_string()).expect("raw null");
        let call = ToolCallView {
            id: "tc-null",
            name: "security_scan",
            args: &null,
        };

        // A gateway before this fix handed the literal arguments to the
        // adapter. "null" is also valid base64, so that write succeeded and
        // the job was admitted under the literal's address.
        let (legacy_job, legacy_reference) = {
            let (store, _binary, blobs) = open_detached_callback_test_stores(root.path());
            let legacy = blobs
                .put_artifact(CALLBACK_ARGUMENTS_MEDIA_TYPE, "null")
                .await
                .expect("legacy write");
            assert_eq!(
                blobs.get(&legacy.blob_id).await.expect("legacy read").data,
                "null"
            );
            let legacy_reference = meerkat::RunnerSpecificationRef::new(legacy.blob_id.to_string())
                .expect("legacy reference");
            let (dispatcher, _bridge, _stdout_rx) =
                detached_callback_test_dispatcher(store.clone(), blobs);
            let context = detached_callback_test_context();
            let plan = resolve_detached_callback_test_plan(&dispatcher, call, &context);
            let (spec, _) = detached_callback_job_spec(
                crate::storage_provider::DEFAULT_MEERKAT_LEVEL_REALM_ID,
                call,
                &context,
                &plan,
            )
            .expect("legacy job spec");
            let legacy_job = meerkat::DetachedJobService::new(store)
                .submit(spec.with_runner_specification_ref(legacy_reference.clone()))
                .await
                .expect("legacy submit");
            (legacy_job, legacy_reference)
        };

        let (store, _binary, blobs) = open_detached_callback_test_stores(root.path());
        let (dispatcher, bridge, mut stdout_rx) =
            detached_callback_test_dispatcher(store.clone(), blobs);
        let replay = submit_detached_callback_test_call(&dispatcher, call)
            .await
            .expect("replayed submit");
        assert_eq!(replay.job_id, legacy_job.job_id.to_string());
        assert!(replay.deduplicated);
        // The admitted job was still queued: its first attempt reads the
        // historical literal through the adapter.
        let start = accept_detached_callback_start(&bridge, &mut stdout_rx).await;
        assert_eq!(start.get("arguments"), Some(&Value::Null));
        assert_eq!(
            start.get("runner_specification_ref"),
            Some(&json!(legacy_reference.as_str()))
        );
        let admitted = store
            .get(&legacy_job.job_id)
            .await
            .expect("read job")
            .expect("admitted job");
        assert_eq!(admitted.machine_state.attempt_count, 1);

        let again = submit_detached_callback_test_call(&dispatcher, call)
            .await
            .expect("second replay");
        assert_eq!(again.job_id, replay.job_id);
        assert!(again.deduplicated);

        // The same call with other arguments is still another submission.
        let changed = serde_json::value::RawValue::from_string(r#"{"target":"lan"}"#.to_string())
            .expect("raw arguments");
        let error = submit_detached_callback_test_call(
            &dispatcher,
            ToolCallView {
                id: "tc-null",
                name: "security_scan",
                args: &changed,
            },
        )
        .await
        .expect_err("changed arguments conflict");
        assert!(
            error
                .to_string()
                .contains(&meerkat::DetachedJobError::SubmissionConflict.to_string()),
            "{error}"
        );

        let jobs = store.list_all(usize::MAX).await.expect("list jobs");
        assert_eq!(jobs.len(), 1);
        assert_eq!(jobs[0].job_id, legacy_job.job_id);
        assert_eq!(
            jobs[0].spec.runner_specification_ref.as_ref(),
            Some(&legacy_reference)
        );
        assert_eq!(jobs[0].revision, admitted.revision);
        assert_eq!(jobs[0].machine_state.attempt_count, 1);
    }

