    /// A configured access path that is missing, a directory, invalid, empty
    /// or not a string refuses initialization (no disabled fallback, no
    /// created file); an omitted or null path keeps access control off.
    #[test]
    fn gateway_runtime_options_refuse_an_unusable_access_config_path() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let missing = tmp.path().join("missing.toml");
        let invalid = tmp.path().join("invalid.toml");
        std::fs::write(&invalid, "enabled = [").expect("write access config");
        for path in [missing.clone(), tmp.path().to_path_buf(), invalid] {
            let params = json!({
                "runtime_options": {
                    "access_config_path": path.to_string_lossy()
                }
            });
            let err = match parse_gateway_runtime_options(&params, None) {
                Ok(_) => panic!("{} must refuse initialization", path.display()),
                Err(err) => err,
            };
            assert!(err.contains("access_config_path"), "{err}");
        }
        assert!(!missing.exists(), "no policy file is created");
        for value in [
            json!(""),
            json!(42),
            json!(true),
            json!({"path": "access.toml"}),
        ] {
            let params = json!({ "runtime_options": { "access_config_path": value.clone() } });
            let err = match parse_gateway_runtime_options(&params, None) {
                Ok(_) => panic!("{value} must refuse initialization"),
                Err(err) => err,
            };
            assert!(err.contains("access_config_path"), "{err}");
        }

        let omitted = parse_gateway_runtime_options(&json!({ "runtime_options": {} }), None)
            .expect("omitted access configuration");
        assert!(omitted.access.is_none(), "access control stays off");
        let null = parse_gateway_runtime_options(
            &json!({ "runtime_options": { "access_config_path": null } }),
            None,
        )
        .expect("null access configuration");
        assert!(null.access.is_none(), "null is an omission");
    }

    /// A configured gating path that is missing, a directory, invalid, empty
    /// or not a string refuses initialization; an omitted or null path keeps
    /// gating off.
    #[test]
    fn gateway_runtime_options_refuse_an_unusable_gating_config_path() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let missing = tmp.path().join("missing.toml");
        let invalid = tmp.path().join("invalid.toml");
        std::fs::write(&invalid, "actions = [").expect("write gating config");
        for path in [missing, tmp.path().to_path_buf(), invalid] {
            let params = json!({
                "runtime_options": {
                    "gating_config_path": path.to_string_lossy()
                }
            });
            let err = match parse_gateway_runtime_options(&params, None) {
                Ok(_) => panic!("{} must refuse initialization", path.display()),
                Err(err) => err,
            };
            assert!(err.contains("gating_config_path"), "{err}");
        }
        for value in [
            json!(""),
            json!(42),
            json!(true),
            json!({"path": "gating.toml"}),
        ] {
            let params = json!({ "runtime_options": { "gating_config_path": value.clone() } });
            let err = match parse_gateway_runtime_options(&params, None) {
                Ok(_) => panic!("{value} must refuse initialization"),
                Err(err) => err,
            };
            assert!(err.contains("gating_config_path"), "{err}");
        }

        for runtime_options in [json!({}), json!({ "gating_config_path": null })] {
            let parsed = parse_gateway_runtime_options(
                &json!({ "runtime_options": runtime_options.clone() }),
                None,
            )
            .expect("omitted gating configuration");
            assert!(
                parsed.gating.action_risk_tiers.is_empty(),
                "{runtime_options} keeps gating off"
            );
            assert_eq!(
                parsed.gating.escalation,
                crate::GatingEscalationRoutes::default()
            );
        }
    }

    /// An empty access or gating path no longer switches the feature off (the
    /// predecessor SDKs dropped it), so the gateway refuses it. The refusal
    /// says that and names how to keep the feature off, instead of a bare read
    /// error for `''`.
    #[test]
    fn an_empty_access_or_gating_path_refusal_names_how_to_keep_the_feature_off() {
        for (option, feature, builder_call, conventional_file) in [
            (
                "access_config_path",
                "access control",
                "accessControl()",
                "config/access.toml",
            ),
            (
                "gating_config_path",
                "gating",
                "gating()",
                "config/gating.toml",
            ),
        ] {
            let params = json!({ "runtime_options": { option: "" } });
            let err = match parse_gateway_runtime_options(&params, None) {
                Ok(_) => panic!("an empty {option} must refuse initialization"),
                Err(err) => err,
            };
            for expected in [
                format!("runtime_options.{option} is empty"),
                format!("an empty path no longer switches {feature} off"),
                format!("omit runtime_options.{option} or set it to null"),
                builder_call.to_string(),
                conventional_file.to_string(),
            ] {
                assert!(
                    err.contains(&expected),
                    "the {option} refusal must say {expected:?}: {err}"
                );
            }
        }
    }

    /// meerkat refuses a profile prompt key that MobKit 0.8.31 and earlier
    /// dropped without a warning, so an upgraded `mob_config` that kept one
    /// stops at init. The refusal keeps meerkat's remedy and adds the upgrade
    /// fact: removing the key keeps the behaviour the deployment had.
    #[test]
    fn a_refused_profile_prompt_key_names_the_upgrade_remedy() {
        for key in ["system_prompt", "prompt", "instructions"] {
            let mob_config = format!(
                "[mob]\nid = \"m\"\n\n[profiles.planner]\nmodel = \"gpt-5.5\"\n{key} = \"Plan.\"\n"
            );
            let err = match parse_mob_config(&mob_config) {
                Ok(_) => panic!("a profile {key} must refuse initialization"),
                Err(err) => err,
            };
            for expected in [
                "Invalid mob_config TOML: ".to_string(),
                format!("profile 'planner' declares '{key}', which a mob profile cannot honour"),
                format!("MobKit 0.8.31 and earlier dropped '{key}' without a warning"),
                "so the key had no effect on the members of profile 'planner'".to_string(),
                "removing the key keeps that behaviour".to_string(),
                "[skills.<id>]".to_string(),
            ] {
                assert!(
                    err.contains(&expected),
                    "the {key} refusal must say {expected:?}: {err}"
                );
            }
        }
    }

